    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("I tre Qul (Mu'awwidhat)", "(Surah al-Ikhlas) Di': Egli è Allah, l'Unico. Allah, l'Autosufficiente. Non genera né nasce. E non c'è nessuno paragonabile a Lui.\n\n(Surah al-Falaq) Di': Cerco rifugio nel Signore dell'alba, dal male di ciò che ha creato, dal male dell'oscurità quando si deposita, dal male di coloro che soffiano sui nodi e dal male dell'invidioso quando invidia.\n\n(Sura an-Nas) Dì: Cerco rifugio nel Signore dell'umanità, nel Re dell'umanità, nel Dio dell'umanità, dal male di chi sussurra in ritirata, che sussurra nei cuori dell'umanità, tra i jinn e l'umanità.", "Le tre Sura tre volte ogni mattina e sera, e prima di dormire, soffiano sulle mani e asciugale sul corpo.", "Recitarle tre volte mattina e sera basta contro tutto."),
        "dua_sabr" to DuaText("Per pazienza e fermezza", "Nostro Signore, infondi su di noi la pazienza, rendi saldi i nostri piedi e aiutaci contro i miscredenti.", "Nei momenti di difficoltà e di confronto.", "Il dua dell'esercito di Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Perdono e protezione dal fuoco", "Nostro Signore, noi abbiamo creduto, quindi perdona i nostri peccati e proteggici dal castigo del Fuoco.", "Un dua coranico.", "Un dua menzionato tra le qualità dei timorati di Dio."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Guida nel nostro affare (Ashab al-Kahf)", "Nostro Signore, concedici la tua misericordia e prepara per noi la giusta guida nella nostra vicenda.", "Il dua del Popolo della Caverna.", "Orientamento nelle decisioni e nelle situazioni difficili."),
        "dua_musa_faqir" to DuaText("Dua di Musa (AS) per Provvedimento", "Mio Signore, ho davvero bisogno di tutto il bene che mi mandi.", "Cercare provviste e bene: il dua di Musa (AS) a Madyan.", "Dopo questo dua, Allah concesse a Musa (AS) una casa, un lavoro e una moglie."),
        "dua_ayyub" to DuaText("Dua di Ayyub (AS) in Malattia", "(Mio Signore,) il male mi ha toccato e Tu sei il Misericordioso dei misericordiosi.", "Nella malattia e nella sofferenza.", "Allah ha rimosso la sofferenza di Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Muori da musulmano (Yusuf AS)", "Creatore dei cieli e della terra, Tu sei il mio Protettore in questo mondo e nell'Aldilà. Fammi morire come musulmano e uniscimi ai giusti.", "Un dua per un buon finale.", "Il dua del profeta Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Rifugio dai sussurri dei diavoli", "Mio Signore, cerco rifugio in Te dai sussurri dei diavoli, e cerco rifugio in Te, mio ​​Signore, affinché non si avvicinino a me.", "Rifugio dai sussurri satanici.", "Un dua coranico di cercare rifugio."),
        "dua_bad_character" to DuaText("Rifugio dal cattivo carattere", "O Allah, cerco rifugio in Te dal cattivo carattere, dalle cattive azioni e dai desideri malvagi.", "Rifugio dal cattivo carattere, dalle azioni e dai desideri.", "Un dua di rifugio dal Profeta ﷺ."),
        "dua_zawal_nimah" to DuaText("Rifugio dalla perdita delle benedizioni", "O Allah, cerco rifugio in Te dalla perdita delle Tue benedizioni, dal cambiamento del benessere che mi hai dato, dalla Tua punizione improvvisa e da tutto il Tuo dispiacere.", "Rifugio dalla perdita delle benedizioni e dalle calamità improvvise.", "Un dua del Profeta ﷺ."),
        "dua_useless_knowledge" to DuaText("Rifugio dalla conoscenza non benefica", "O Allah, cerco rifugio in Te dalla conoscenza che non giova, da un cuore che non ha paura, da un'anima che non è mai soddisfatta e da un dua a cui non viene data risposta.", "Rifugio dalla conoscenza inutile e un cuore senza timore di Allah.", "Un dua di rifugio dal Profeta ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Conoscenza utile e Rizq Halal", "O Allah, ti chiedo conoscenza benefica, provvista pura e azioni accettate.", "Dopo la preghiera del Fajr.", "Il Profeta ﷺ disse questo dopo il salam di Fajr."),
        "dua_leprosy_diseases" to DuaText("Rifugio da malattie gravi", "O Allah, mi rifugio in Te dalla vitiligine, dalla follia, dalla lebbra e da tutte le malattie malvagie.", "Protezione da malattie gravi.", "Una Sunnah dua per preservare la salute."),
        "dua_fear_people" to DuaText("Paura dei nemici o degli oppressori", "O Allah, ti poniamo davanti a loro e cerchiamo rifugio in te dal loro male.", "Quando si teme il danno di un popolo o di una persona.", "Il Profeta ﷺ disse questo quando temeva un popolo."),
        "dua_shirk_protection" to DuaText("Protezione dallo Shirk nascosto", "O Allah, mi rifugio in Te dall'associare consapevolmente qualsiasi cosa a Te, e cerco il Tuo perdono per ciò che faccio inconsapevolmente.", "Per evitare di mettersi in mostra e di sottrarsi nascostamente.", "Lo sottrarsi nascosto è più nascosto dello strisciare di una formica."),
        "dua_rain" to DuaText("Quando piove", "O Allah, (invia) una pioggia benefica.", "Quando piove.", "La pioggia è un momento in cui i duas sono accettati."),
        "dua_after_rain" to DuaText("Dopo la pioggia", "Ci è stata data la pioggia per la generosità di Allah e la Sua misericordia.", "Dopo la pioggia.", "Chi dice questo crede in Allah."),
        "dua_istisqa" to DuaText("Chiedere la pioggia (Istisqa)", "O Allah, mandaci la pioggia (tre volte).", "Quando non c'è pioggia.", "Il Profeta ﷺ fece questo dua nel sermone del venerdì e piovve."),
        "dua_heavy_rain" to DuaText("Pioggia eccessiva", "O Allah, (lascialo cadere) intorno a noi e non su di noi.", "Quando piove troppo.", "Le nuvole si allontanarono attraverso il dua del Profeta ﷺ."),
        "dua_wind" to DuaText("Quando soffia il vento", "O Allah, ti chiedo il suo bene, il bene in lui e il bene di ciò con cui è stato inviato, e cerco rifugio in Te dal suo male, dal male in esso e dal male di ciò con cui è stato inviato.", "Quando soffia un forte vento o una tempesta.", "Il Profeta ﷺ fece questo dua durante i temporali."),
        "dua_thunder" to DuaText("Udire il tuono", "Gloria a Colui che il tuono glorifica con la sua lode e gli angeli per timore di lui.", "Udire il tuono – la pratica di Abdullah ibn az-Zubayr (RA).", "Tratto dalla Sura ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Vedere la Luna Nuova", "O Allah, lascia che questa luna sorga su di noi con benedizione, fede, sicurezza e Islam. (O luna,) il mio Signore e il tuo Signore è Allah.", "Vedendo la luna nuova.", "La Sunnah dua per ogni nuovo mese."),
        "dua_janaza_adult" to DuaText("Preghiera Janaza (Adulto)", "O Allah, perdona i nostri vivi e i nostri morti, i presenti e gli assenti, i nostri giovani e i nostri vecchi, i nostri uomini e le nostre donne. O Allah, chiunque di noi mantieni in vita, mantienilo in vita secondo l'Islam, e chiunque di noi farai morire, fallo morire secondo la fede.", "Dopo il terzo takbir della preghiera funebre.", "La Sunnah dua per un adulto deceduto."),
        "dua_janaza_child" to DuaText("Preghiera di Janaza (bambino)", "O Allah, rendilo un precursore (e un ospite) per noi, rendilo una ricompensa e un tesoro per noi e rendilo un intercessore per noi la cui intercessione è accettata.", "Nella preghiera funebre di un bambino (per una bambina dire 'ij'alhā').", "La Sunnah dua praticata dagli Hanafiti."),
        "dua_mayyit_awf" to DuaText("Dua dettagliata per il defunto", "O Allah, perdonalo, abbi pietà di lui, donagli benessere e perdonalo. Rendi onorevole la sua accoglienza e spaziosa la sua tomba, lavalo con acqua, neve e grandine e purificalo dai peccati come una veste bianca si monda dalla sporcizia.", "Nella preghiera funebre o per il defunto.", "Awf ibn Malik (RA) avrebbe voluto essere lui quella persona deceduta."),
        "dua_visiting_graves" to DuaText("Visitare le tombe", "La pace sia con voi, o credenti e musulmani abitanti di queste case. Anche noi, se Allah vuole, ci uniremo a voi. Chiedo ad Allah il benessere per noi e per voi.", "Quando entri nel cimitero.", "Visitare le tombe ricorda la morte e l'Aldilà."),
        "dua_closing_eyes" to DuaText("Dopo aver chiuso gli occhi del defunto", "O Allah, perdona (nome), innalza il suo rango tra i guidati, sii il suo successore tra coloro che lascia dietro di sé. Perdona noi e lui, o Signore dei mondi; rendi spaziosa la sua tomba e riempila di luce.", "Quando si chiudono gli occhi del defunto (menzionando il suo nome).", "Il Profeta ﷺ fece questo dua per Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Condoglianze (Ta'ziyah)", "Sicuramente ad Allah appartiene ciò che ha preso e a Lui appartiene ciò che ha dato, e tutto con Lui ha un termine stabilito, quindi sii paziente e spera nella ricompensa.", "Porgere le condoglianze ad una famiglia dopo una morte.", "Il Profeta ﷺ ha inviato questo messaggio a sua figlia."),
        "dua_placing_in_grave" to DuaText("Deposizione del defunto nella tomba", "Nel nome di Allah e sulla via del Messaggero di Allah ﷺ.", "Quando si abbassa il defunto nella tomba.", "La Sunnah dua della sepoltura."),
        "dua_sneezing" to DuaText("Starnuti", "Ogni lode è per Allah. — Che Allah abbia pietà di te. — Possa Allah guidarti e sistemare i tuoi affari.", "Sullo starnuto; l'ascoltatore dice \"Yarhamukallah\", poi quello che ha starnutito risponde.", "È uno dei diritti di un musulmano su un altro musulmano."),
        "dua_toilet_enter" to DuaText("Entrando nella toilette", "Nel nome di Allah. O Allah, cerco rifugio in Te dai jinn impuri maschili e femminili.", "Prima di entrare nella toilette con il piede sinistro.", "Bismillah diventa uno schermo tra il jinn e la persona."),
        "dua_toilet_exit" to DuaText("Uscendo dal bagno", "(O Allah,) Cerco il Tuo perdono.", "Quando si esce dalla toilette con il piede destro.", "Il Profeta ﷺ disse questo uscendo dal bagno."),
        "dua_thanking" to DuaText("Ringraziare qualcuno", "Che Allah ti ricompensi con il bene.", "Quando qualcuno ti fa un favore.", "Chi dice questo ha espresso pienamente il suo ringraziamento."),
        "dua_love_for_allah" to DuaText("Quando qualcuno dice \"Ti amo per Allah\"", "Possa Lui (Allah), per amore del quale mi ami, amarti.", "Quando qualcuno dice \"Ti amo per amore di Allah\".", "La Sunnah risponde all'amore per amore di Allah."),
        "dua_seeing_muslim_smile" to DuaText("Saluto (Salaam)", "La pace sia con te, e la misericordia di Allah e le Sue benedizioni.", "Quando incontri un musulmano.", "Dire il salam completo fa guadagnare trenta buone azioni."),
        "dua_dressing" to DuaText("Vestirsi", "Ogni lode va ad Allah che mi ha rivestito di questo e me lo ha fornito senza alcun potere o potere da parte mia.", "Quando mi vesto.", "La buona novella del perdono dei peccati passati."),
        "dua_rooster_donkey" to DuaText("Ascoltare un gallo o un asino", "O Allah, ti chiedo la Tua generosità (gallo). — Cerco rifugio in Allah da Shaytan, il maledetto (asino).", "Sentendo un gallo chiedere la generosità di Allah; sentendo un asino ragliare cercare rifugio da Shaytan.", "Il gallo vede un angelo e l'asino vede un diavolo."),
        "dua_something_liked" to DuaText("Vedere qualcosa di ammirevole (contro il malocchio)", "Ciò che Allah ha voluto. O Allah, benedicilo.", "Vedendo qualcosa di ammirevole appartenente a qualcuno, prega per la benedizione.", "Pregare per la benedizione previene il malocchio."),
        "dua_sell_buy_debt_repaid" to DuaText("Quando si ripaga un debito", "Che Allah ti benedica nella tua famiglia e nella tua ricchezza.", "Per il creditore nel ripagare un debito.", "Il rendimento di un prestito è il ringraziamento e il rimborso."),
        "dua_talbiyah" to DuaText("Talbiyah", "Eccomi, o Allah, eccomi. Eccomi, non hai partner, eccomi. Sicuramente ogni lode, benedizione e dominio sono tuoi. Non hai un partner.", "Ad alta voce dopo essere entrato in ihram.", "L'emblema di Hajj e Umrah."),
    )
